System.Diagnostics.Debug.WriteLine("ciao");


double raw       = 0;
double filtered  = 0;
double minVal    = 0;
double maxVal    = 0;
double highTh    = 0;
double lowTh     = 0;
double coeff     = 0;
double reset     = 0;

// Exponential low-pass filter: y[n] = alpha*x[n] + (1-alpha)*y[n-1]
var alpha = Math.Max(0.01, Math.Min(1.0, coeff));
filtered = alpha * raw + (1.0 - alpha) * filtered;

// Track min/max
if (raw < minVal) minVal = raw;
if (raw > maxVal) maxVal = raw;

// Rate of change (difference between raw and filtered)
var roc = raw - filtered;

// Alarm state
string alarmState;
if (raw > highTh)
    alarmState = "HIGH";
else if (raw < lowTh)
    alarmState = "LOW";
else
    alarmState = "Normal";
